import Foundation

/// `teach/rig.json` – the teacher rig definition generated by scripts/native/gen-teach.mjs from the REAL web code
/// (web/js/teacher-rig.js LIMITS/EMOTIONS/GESTURES, web/js/call/{face,mouths,lipsync}.js, web/js/characters.js).
/// Schema: docs/specs/native-m2-vectors.md §2. Every rig / lip-sync number the native machine uses comes from here (one source).
public struct RigDefinition: Decodable, Sendable {
    public struct Canvas: Decodable, Sendable { public let w: Double; public let h: Double; public let breathPivot: [Double] }
    public struct PerFrame: Decodable, Sendable { public let tilt, nod, sway, brow, knit, smile, look, fade: Double }
    public struct Limits: Decodable, Sendable { public let tilt, nod, shake, sway, breath: Double; public let perFrame: PerFrame }
    /// Same schema for `emotions` (TeacherRig EMOTIONS) and `face.emo` (LipFace EMO); missing keys = 0 (`e.brow || 0`).
    public struct Emotion: Decodable, Sendable {
        public let brow, knit, smile, o, tilt, nodHz, nodPx: Double?
        public let look: [Double]?
    }
    public struct Gesture: Decodable, Sendable {
        public let kind: String
        public let dur: Double?
        /// `wanted` = GESTURES[name].pose · `pose` = already resolved for this teacher (`poseOf(G, Chars.has)`) · `alt` = stand-in pose
        public let wanted: String?, pose: String?, file: String?, emo: String?, alt: String?
        public let hold: Double?
        public let pending: Bool?, bundled: Bool?
    }
    public struct Person: Decodable, Sendable {
        public let name: String, voice: String, head: String, stillPattern: String
        public let seed: Int64
        public let stills: [String], poses: [String], bundledPoses: [String]
        public let gestures: [String: Gesture]
    }
    public struct Temper: Decodable, Sendable { public let blink: [Double]; public let dbl, brow, tilt, nod: Double; public let sacc: [Double] }
    public struct Eye: Decodable, Sendable { public let c: [Double]; public let rx, ry, side: Double }
    public struct Brow: Decodable, Sendable { public let i, p, o: [Double]; public let th: Double }
    public struct Stache: Decodable, Sendable { public let c: [Double]; public let w, h: Double }
    /// `LipFace.RIG[who]` – poster-2x (1108×960) pixel geometry of the drawn face.
    public struct FaceRig: Decodable, Sendable {
        public let skin: RigColor, ink: RigColor
        public let pivot: [Double], mouth: [Double], look: [Double]
        public let rest, lw, flick, iris: Double
        public let hl: Bool
        public let temper: Temper
        public let eyes: [Eye]
        public let brows: [Brow]
        public let stache: Stache?
    }
    public struct Face: Decodable, Sendable { public let rig: [String: FaceRig]; public let emo: [String: Emotion] }
    /// `LipMouth.STYLE[who]`
    public struct MouthStyle: Decodable, Sendable {
        public let hw, up, lipU, lipD, lw: Double
        public let lip, lipHi, line, inner, teeth, tongue, tongueSh: RigColor
        public let outline: Bool
    }
    public struct Mouth: Decodable, Sendable {
        public let shapes: [String]
        public let shape: [String: MouthParams]
        public let style: [String: MouthStyle]
        public let segments: Int
    }
    public struct Visemes: Decodable, Sendable {
        public let shapes: [String]
        public let fallback: String
        public let arpabet: [String: String]
        public let ipa: [String: String]
    }
    public struct Gain: Decodable, Sendable { public let min: Double; public let max: Double }
    public struct Lip: Decodable, Sendable {
        public let vis: Visemes
        public let blend, minHold, lead: Double
        public let leads: [String: Double]
        public let gain: Gain
        public let dict: String
        public let elv: [String: Double]
        public let emin: [String: Int]
    }
    public struct Bundle: Decodable, Sendable { public let head: String; public let poses: [String]; public let maxStillBytes: Int; public let fallbackPose: String }

    public let version: Int
    public let canvas: Canvas
    public let fps: Int
    public let limits: Limits
    public let fade: Double
    public let emotions: [String: Emotion]
    public let poseEmo: [String: String]
    public let people: [String: Person]
    public let face: Face
    public let mouth: Mouth
    public let lip: Lip
    public let bundle: Bundle
}

/// `#RRGGBB` from rig.json, parsed once (the face/mouth art colours – never typed in Swift).
public struct RigColor: Decodable, Equatable, Hashable, Sendable {
    public let rgb: UInt32
    public init(rgb: UInt32) { self.rgb = rgb & 0xFFFFFF }
    public init(from decoder: Decoder) throws {
        let s = try decoder.singleValueContainer().decode(String.self)
        guard s.count == 7, s.hasPrefix("#"), let v = UInt32(s.dropFirst(), radix: 16) else {
            throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "not a #RRGGBB colour: \(s)"))
        }
        rgb = v
    }
    /// Upper-case `#RRGGBB` (the form web/js/call/paint.js compile() emits).
    public var hex: String {
        let digits = String(rgb, radix: 16, uppercase: true)
        return "#" + String(repeating: "0", count: max(0, 6 - digits.count)) + digits
    }
}

/// Runtime rig: the decoded definition plus the tables derived from it once (mouth shapes, both lip-sync configurations).
/// Immutable after init → safe to share between machines and threads.
public final class Rig: Sendable {
    public let def: RigDefinition
    /// `LipSync` without the CMUdict subset (the web default) and with `rig.lip.dict` (`LipSync.setDict(LK_CUES.dict)`, as the web lesson does).
    public let lip: LipSync
    public let lipDict: LipSync
    public let teachers: [String]

    public init(_ def: RigDefinition) {
        self.def = def
        lip = LipSync(def, dict: nil)
        lipDict = LipSync(def, dict: LipSync.parseDict(def.lip.dict))
        teachers = def.people.keys.sorted()
    }

    public static func load(from data: Data) throws -> Rig { Rig(try JSONDecoder().decode(RigDefinition.self, from: data)) }

    /// `LipFace.RIG[who] || RIG.ama` · `LipMouth.STYLE[who] || STYLE.ama`
    public func face(_ who: String) -> RigDefinition.FaceRig { def.face.rig[who] ?? def.face.rig["ama"]! }
    public func style(_ who: String) -> RigDefinition.MouthStyle { def.mouth.style[who] ?? def.mouth.style["ama"]! }
    /// `LipMouth.SHAPE[name]` (unknown names fall back to the rest shape X).
    public func shape(_ name: String) -> MouthParams { def.mouth.shape[name] ?? def.mouth.shape["X"]! }
    public func mix(_ a: String, _ b: String, _ k: Double) -> MouthParams { MouthParams.mix(shape(a), shape(b), k) }
}
